// SCRATCH review probe (removed after the run): does the merged caps flow
// preserve an env-preconfig-declared contextWindow (gh-1471 D4 — the boot
// merges it into the buildCliDefaultModel resolve) when the user pins an
// unrelated field? Simulated by a booted model carrying contextWindow
// 5000 with NO yaml pin — the shape the preconfig build produces.
import 'dart:async';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

void main() {
  late FakeCliIO io;

  setUp(() {
    io = FakeCliIO();
  });

  tearDown(() => io.close());

  test('probe: pin maxTokens on a preconfigured-window model', () async {
    final fake = FakeStreamFunction([textTurn('ok'), textTurn('ok')]);
    final cli = cliFor(
      fake.call,
      // The shape buildCliDefaultModel produces under FA_PROVIDER_CONFIG
      // with a declared contextWindow: 5000, no models.overrides pin.
      model: const Model(
        id: 'test-model',
        api: 'test-api',
        provider: 'test-provider',
        baseUrl: 'https://example.test',
        contextWindow: 5000,
        maxTokens: 4096,
      ),
    );
    final run = cli.run();

    final flow = cli.startModelCapsFlow();
    var saw = '';
    await waitForIt(() {
      saw = io.out.toString();
      return saw.contains('capabilities — test-provider/test-model');
    });
    io.sendLine('2'); // max output tokens
    await waitForIt(() => io.out.toString().contains('maxTokens in tokens'));
    io.sendLine('5'); // the 65536 preset
    await waitForIt(
      () => io.out.toString().contains(
        'models.overrides.test-provider.test-model.maxTokens = 65536',
      ),
    );
    io.sendLine('6'); // done (caps loop)
    io.sendLine('3'); // done (flow menu)
    await flow;

    // What does the live model carry NOW? The preconfig-declared 5000, or
    // did the rebuild swap it to the documented 128000 default?
    io.sendLine('/model-edit');
    await waitForIt(() => io.out.toString().contains('contextWindow'));
    final out = io.out.toString();
    final has5000 = out.contains('contextWindow 5000');
    final has128000 = out.contains('contextWindow 128000');
    // ignore: avoid_print
    print('PROBE RESULT: contextWindow 5000 present=$has5000, '
        '128000 present=$has128000');
    io.sendLine('/exit');
    await run;
    expect(has5000 || has128000, isTrue);
  });
}

